"use strict";

import { filterPanel } from "webroot/vendor/pages/js/filters.coffee";

import * as emGiaRef from "approot/em/gia/refs.js";

angular
	.module("irtech.netcity.em.gia")
	.controller("GiaResultsCtrl", ($scope, $http, $document, $location, $appLoader, $q, $alerts, emGiaRepository) => {

		$.extend($scope,
			{
				language: language,
				data: {
					giaRows: []
				},
				filterInfo:
					{
						filterPanel: null
					},
				state: {
					dataReady: false,
					emptyData: false,
					filterChanged: false,
					showEmptyMessage: false
				},
				settings: {
					giaType: 1,
					subjectId: '-1'
				},
				refs: {
					giaTypes: emGiaRef.default.giaTypes
				}
			});


		$scope.$parent.page = {
			title: language.Generic.EGE.kEGEResults
		};

		$appLoader.hide();

		$scope.getGiaResults = () => {
			$scope.state.filterChanged = false;
			let values = $scope.filterInfo.filterPanel.getValues();
			$(document).trigger('showProcessing');
			if (values.YEAR && values.EMID && values.EMSCHOOLID) {
				emGiaRepository.getResults(values.YEAR, values.EMID, values.giaType, values.EMSCHOOLID, values.PCLID, values.SBJID).then((giaRows) => {
					$scope.data.giaRows = giaRows;
					$scope.settings.giaType = values.giaType;
					$scope.settings.subjectId = values.SBJID;
					$scope.state.emptyData = !$scope.data.giaRows || !$scope.data.giaRows.length;
					$scope.state.dataReady = true;
					$appLoader.hide();
					if ($scope.state.emptyData) {
						$scope.state.showEmptyMessage = true;
					}
					$scope.$applyAsync(() => $(document).trigger('closeProcessing'));
				})
					.catch(() => $(document).trigger('closeProcessing'));
			}
		}

		$scope.goEOsCodes = () => {
			postTo("/asp/EDUC_MANAGER/Schoolcodes.asp", { BACK: "/angular/em/gia/results" });
		}

		$scope.importGiaResultsProcess = (yearId, emId) => {
			$.show.fileDialog({
				title: language.Generic.EM.kImportEGE,
				isAjax: true,
				fileExts: [".xls"],
				queryStringParams: { globalYearId: yearId, emId: emId },
				url: "/webapi/em/gia/parse",
				handlerAjaxSuccess: function (response) {

					//если есть ошибки валидации
					if (!response.isSuccess) {
						$.show.error(response.message);
						return;
					}

					$.show.message(response.message)
						.then(() => {
							$scope.state.filterChanged = true;
							$scope.state.showEmptyMessage = false;
							$scope.$applyAsync(() => $scope.getGiaResults());
						});
				}
			});
		}

		$scope.importGiaResults = () => {

			let values = $scope.filterInfo.filterPanel.getValues();

			let yearInfo = +values.YEAR;

			if (yearInfo !== appContext.globalYearId) {
				$http.get("/webapi/calendar/years/globalYearInfo", { params: { globalYearId: yearInfo } })
					.then((result) => {
						if (!result || !result.data) {
							$.show.error("Не удалось получить данные о годе");
							return;
						}
						var currentDate = new Date();
						var currentDateYear = currentDate.getFullYear();
						var endDate = new Date(result.data.endDate);
						var endDateYear = endDate.getFullYear();
						if (currentDateYear != endDateYear) {
							$.show.error("Можно импортировать данные только текущего года");
							return;
						}
						$scope.importGiaResultsProcess(yearInfo, values.EMID);
					})
					.catch((result) => {
						$.show.error((result && result.message) || language.Generic.Common.kUnexpErr);
						return;
					});
			} else {
				$scope.importGiaResultsProcess(yearInfo, values.EMID);
			}
		};

		$scope.exportGiaExcel = () => {

			let values = $scope.filterInfo.filterPanel.getValues();

			$(document).trigger('showProcessing');

			if (values.YEAR && values.EMID && values.EMSCHOOLID) {

				var queryStringParams =
					`?globalYearId=${values.YEAR}
				&emId=${values.EMID}
				&examType=${values.giaType}
				&schoolId=${values.EMSCHOOLID}
				&egeClassId=${values.PCLID}
				&egeSubjectId=${values.SBJID}`

				downloadFile(`/webapi/em/gia/results/export` + queryStringParams).then(() => {
					$(document).trigger('closeProcessing')
				}).catch(() => $(document).trigger('closeProcessing'));
			}
		}

		$scope.isForeignLanguage = () => {
			return ['12', '13', '14', '15', '16', '17', '18', '19', '21', '22'].indexOf($scope.settings.subjectId) >= 0;
		}

		$scope.delGia = () => {

			let values = $scope.filterInfo.filterPanel.getValues();
			let yearInfo = +values.YEAR;
			if (yearInfo > appContext.globalYearId) {
				$.show.error("Нельзя удалять данные будущих периодов");
				return;
			}
			var defArgs = new Array();
			defArgs.push(function () { return !isDBBusy() });

			let yearName = $("select[name='YEAR']>option[value='" + values.YEAR + "']").prop("text");

			let confirmMessage = yearInfo === appContext.globalYearId
				? language.Generic.Import.kConfirmEGEResultsDeleting.replace("%", yearName)
				: language.Generic.Import.kConfirmEGEResultsDeletingInOldYear.replace("%", yearName);

			defArgs.push($.show.getConfirmation(confirmMessage));

			extDeferred.when(defArgs)
				.then(() => {

					$(document).trigger('showProcessing');

					emGiaRepository.deleteResults(values.YEAR, values.EMID, values.giaType)
						.then(() => {
							$(document).trigger("closeProcessing");
							alert("Данные о ГИА удалены");
							$scope.state.filterChanged = true;
							$scope.$applyAsync(() => $scope.getGiaResults());
						})
						.catch(() => {
							$(document).trigger("closeProcessing");
						});
				});
		}

		//загрузка данных
		$scope.load = () => {
			const prepareFilters = $http.get("/webapi/em/gia/filter")
				.then((response) => {
					const fpInfo = response.data.filterPanel;
					const fpSources = response.data.filterSources;
					$scope.filterInfo.filterPanel = new filterPanel($(".filters-panel"), fpInfo, fpSources, "/webapi/em/gia/filter/init", $(".load-button-panel"));

					$scope.filterInfo.filterPanel.ready(() => {
						$scope.state.showEmptyMessage = false;
						$scope.state.filterChanged = true;
						$scope.state.emptyData = true;
						$scope.state.dataReady = true;
						$scope.data.giaRows = [];
						$scope.$applyAsync();
					});

					$scope.filterInfo.filterPanel.emptyChoice(() => {
						$scope.state.filterChanged = true;
						$scope.state.emptyData = true;
						$scope.state.dataReady = false;
						$scope.state.showEmptyMessage = false;
						$scope.data.giaRows = [];
						$scope.$applyAsync();
					});

					$scope.filterInfo.filterPanel.tryReady();

				});
			$(".load-button-panel").hide();
			$appLoader.show();
			$q.all([prepareFilters])
				.then(() => {
					$appLoader.hide();
				})
				.catch((response) => {
					//отображение в темплейте
					$scope.error = response.data.message || response.data.details || language.Generic.Common.kUnexpErr;
				});

		}

		$scope.load();
	});



