"use strict";

import { BaseRepository } from "approot/global/repository.js";

class EmGiaRepository extends BaseRepository {

	getResults(globalYearId, emId, examType, schoolId, egeClassId, egeSubjectId) {
		return this.$http.get("/webapi/em/gia/results", { params: { globalYearId, emId, examType, schoolId, egeClassId, egeSubjectId } })
			.then((response) => {
				return response.data;
			})
			.catch(this.handleError);
	}

	deleteResults(globalYearId, emId, examType) {
		return this.$http.delete("/webapi/em/gia/results", { params: { globalYearId, emId, examType } })
			.then(() => {
			})
			.catch(this.handleError);
	}

}

angular
	.module("irtech.netcity.em.gia")
	.factory("emGiaRepository", ($http, $dialogs, $alerts) => new EmGiaRepository($http, $dialogs, $alerts))
;


